from common import *
R=[{'sourceId':'bertsekas','locator':'Chương 1–6: Probability, Random Variables, Expectation, Limit Theorems và Bernoulli/Poisson Processes'},{'sourceId':'yates','locator':'Chương 1–5, 9 và 13 (mục giới thiệu và roadmap đã kiểm tra qua OCR)'},{'sourceId':'gnedenko','locator':'Phần I: Probabilities; Phần II: Random Variables'}]
s=[]
s.append(S('models','Mô hình xác suất và biến cố',r'Một mô hình gồm không gian mẫu, họ biến cố và xác suất thỏa không âm, chuẩn hóa và cộng được trên các biến cố rời nhau. Quy tắc $P(A\cup B)=P(A)+P(B)-P(A\cap B)$ không đòi độc lập. § Trong mô hình hữu hạn đồng khả năng, xác suất bằng tỷ lệ số phần tử. Với lấy mẫu có hoặc không hoàn lại, không gian mẫu khác nhau; mô hình phải được chọn trước khi tính.',r'Mô tả phép thử và kết quả sơ cấp. § Xác định các biến cố và phần giao. § Dùng tiên đề hoặc đếm đồng khả năng.','Các biến cố rời nhau có xác suất dương không thể độc lập.',[
E(r'Gieo xúc xắc công bằng, tính xác suất số chẵn hoặc lớn hơn 4.',r'A gồm 2,4,6 và B gồm 5,6. § Giao chỉ có 6, nên hợp có $3+2-1=4$ phần tử. § Chia cho 6 kết quả đồng khả năng.',r'$P(A\cup B)=2/3$.','Trừ phần giao để không đếm số 6 hai lần.'),
E(r'Một hệ có xác suất hỏng trong ngày 0.03. Xác suất không hỏng?',r'Biến cố không hỏng là phần bù của hỏng. § Hai biến cố rời nhau và hợp là toàn không gian. § Dùng chuẩn hóa $P(A^c)=1-P(A)$.',r'$0.97$.','Phần bù thường dễ tính hơn liệt kê mọi tình huống thành công.'),
E(r'Lấy hai linh kiện không hoàn lại từ hộp có 3 tốt, 2 lỗi. Xác suất cả hai tốt?',r'Có $\binom52=10$ cặp không thứ tự đồng khả năng. § Cặp tốt có $\binom32=3$. § Chia số cặp thuận lợi cho tổng số cặp.',r'$3/10$.','Không hoàn lại làm chất lượng lần sau phụ thuộc kết quả lần đầu.'),
E(r'Nếu $P(A)=0.7$, $P(B)=0.6$, tìm chặn dưới của $P(A\cap B)$.',r'Xác suất hợp không vượt 1. § Từ $P(A\cap B)=P(A)+P(B)-P(A\cup B)$ suy ra ít nhất 0.3. § Chặn này đạt được khi hợp chiếm toàn không gian.',r'$P(A\cap B)\ge0.3$.','Không có giả thiết độc lập thì chỉ nên kết luận bằng chặn hoặc công thức tổng quát.'),
E(r'Hai biến cố rời nhau có xác suất 0.2 và 0.4. Chúng có độc lập không?',r'Giao rỗng nên xác suất giao bằng 0. § Nếu độc lập thì xác suất giao phải bằng $0.2\cdot0.4=0.08$. § Hai giá trị khác nhau.',r'Không độc lập.','Rời nhau là không xảy ra đồng thời; độc lập là không cung cấp thông tin cho nhau.')],R))
s.append(S('conditioning','Xác suất có điều kiện, Bayes và chẩn đoán',r'Với $P(B)>0$, $P(A\mid B)=P(A\cap B)/P(B)$. Công thức xác suất toàn phần dùng một phân hoạch: $P(B)=\sum_iP(B\mid A_i)P(A_i)$. Bayes đảo chiều điều kiện bằng cách chuẩn hóa các trọng số. § Trong chẩn đoán, xác suất bệnh trước kiểm tra ảnh hưởng mạnh giá trị dự đoán dương; độ nhạy không đồng nhất với xác suất mắc bệnh sau kết quả dương.',r'Xác định điều kiện và tỷ lệ nền. § Tính mẫu số bằng xác suất toàn phần. § Chuẩn hóa và kiểm tra tổng hậu nghiệm bằng 1.','Không được thay xác suất A biết B bằng xác suất B biết A.',[
E(r'Bệnh có tỷ lệ 1%, độ nhạy 90%, dương giả 5%. Tính xác suất bệnh sau dương tính.',r'Xác suất bệnh và dương là $0.01\cdot0.9=0.009$. § Xác suất dương tổng là $0.009+0.99\cdot0.05=0.0585$. § Chia hai xác suất để nhận $0.009/0.0585$.',r'$P(B\mid+)=2/13\approx15.38\%$.','Kết quả dương không đồng nghĩa xác suất bệnh bằng độ nhạy 90%.'),
E(r'Nhà máy A cung cấp 60% sản phẩm, tỷ lệ lỗi 2%; B cung cấp 40%, lỗi 5%. Tính tỷ lệ lỗi chung.',r'Tách theo nguồn A hoặc B, một phân hoạch. § Lỗi từ A đóng góp $0.6\cdot0.02=0.012$. § Lỗi từ B đóng góp $0.4\cdot0.05=0.02$; cộng hai phần.',r'$P(L)=0.032=3.2\%$.','Tỷ lệ tổng là trung bình có trọng số, không phải trung bình cộng hai tỷ lệ.'),
E(r'Với dữ liệu trên, sản phẩm lỗi có xác suất đến từ B là bao nhiêu?',r'Tử số là $P(B\cap L)=0.02$. § Mẫu số là tỷ lệ lỗi chung 0.032. § Bayes cho tỷ số $0.02/0.032$.',r'$P(B\mid L)=0.625$.','Nguồn chiếm ít sản lượng hơn vẫn có thể chiếm đa số sản phẩm lỗi.'),
E(r'Xúc xắc cho biết kết quả chẵn. Xác suất kết quả lớn hơn 3?',r'Sau điều kiện, chỉ còn 2,4,6 với xác suất bằng nhau. § Hai kết quả 4,6 lớn hơn 3. § Xác suất điều kiện là $2/3$.',r'$2/3$.','Điều kiện làm co không gian mẫu hiệu dụng.'),
E(r'Hai lần tung đồng xu độc lập. Biết lần đầu ngửa, xác suất lần hai ngửa?',r'Giao hai lần ngửa có xác suất $1/4$. § Điều kiện lần đầu ngửa có xác suất $1/2$. § Chia được $(1/4)/(1/2)=1/2$.',r'$1/2$.','Độc lập nghĩa là biết kết quả lần đầu không thay đổi phân bố lần sau.')],R))
s.append(S('discrete','Biến ngẫu nhiên rời rạc và các phân bố chuẩn',r'PMF $p_X(k)=P(X=k)$ không âm và có tổng 1. Bernoulli mô tả một thử nghiệm thành/bại; binomial đếm số thành công trong n thử độc lập cùng p; geometric đếm số lần thử tới thành công đầu. § Poisson với tham số lambda có PMF $e^{-\lambda}\lambda^k/k!$, phù hợp đếm khi các giả thiết quá trình thích hợp được kiểm tra. Không chọn phân bố chỉ vì dữ liệu có số nguyên.',r'Xác định đại lượng đếm và miền giá trị. § Kiểm tra giả thiết số lần thử, độc lập và tham số. § Viết PMF rồi tính xác suất.','Hai quy ước geometric bắt đầu từ 0 và 1 có kỳ vọng khác nhau.',[
E(r'Tung đồng xu công bằng 4 lần. Xác suất đúng 2 lần ngửa?',r'$X\sim\operatorname{Bin}(4,1/2)$. § Chọn hai vị trí ngửa có $\binom42=6$ cách. § Mỗi chuỗi xác suất $1/16$, nên nhân được $6/16$.',r'$3/8$.','Hệ số tổ hợp đếm vị trí các thành công.'),
E(r'Thử độc lập xác suất thành công 0.2. Xác suất thành công đầu ở lần 3?',r'Dùng geometric trên $\{1,2,\ldots\}$. § Hai lần đầu phải thất bại, lần ba thành công. § Xác suất là $0.8^2\cdot0.2$.',r'$0.128$.','Sự kiện này xác định một chuỗi có thứ tự, không cần hệ số tổ hợp.'),
E(r'$X\sim\operatorname{Pois}(2)$. Tính $P(X=0)$.',r'Thay k bằng 0 vào PMF. § $2^0=1$ và $0!=1$. § Chỉ còn hệ số mũ $e^{-2}$.',r'$P(X=0)=e^{-2}\approx0.1353$.','Tham số 2 cũng là kỳ vọng số sự kiện trong khoảng quan sát.'),
E(r'Một biến nhận 0,1,2 với xác suất c,2c,3c. Tìm c và $P(X\ge1)$.',r'Chuẩn hóa cho $c+2c+3c=1$. § Suy ra $c=1/6$. § Xác suất từ 1 trở lên là $2/6+3/6$.',r'$c=1/6$, $P(X\ge1)=5/6$.','Luôn kiểm tra tính chuẩn hóa trước khi tính các đặc trưng khác.'),
E(r'Lấy 2 vật không hoàn lại từ 4 đỏ, 6 xanh. Xác suất có đúng một đỏ?',r'Tổng số cặp là $\binom{10}2=45$. § Chọn một đỏ và một xanh có $4\cdot6=24$ cách. § Chia được $24/45$.',r'$8/15$.','Đây là siêu bội, không phải binomial do lấy không hoàn lại.')],R))
s.append(S('continuous','Biến liên tục, CDF và phân bố mũ–chuẩn',r'Mật độ f không phải xác suất tại một điểm: $P(a<X\le b)=\int_a^bf(x)dx$, còn $F_X(x)=P(X\le x)$. Với biến có mật độ, xác suất một điểm bằng 0. § Mũ tốc độ lambda có mật độ $\lambda e^{-\lambda x}$ trên $x\ge0$ và tính không nhớ. Chuẩn được chuẩn hóa bằng $Z=(X-\mu)/\sigma$; phải phân biệt độ lệch chuẩn sigma với phương sai sigma bình phương.',r'Ghi miền hỗ trợ và chuẩn hóa mật độ. § Tính xác suất qua tích phân hoặc CDF. § Kiểm tra đơn vị và tham số hóa.','Giá trị mật độ lớn hơn 1 không làm mô hình sai; tích phân mới phải bằng 1.',[
E(r'$X\sim U(2,6)$. Tính $P(3<X<5)$.',r'Mật độ là $1/(6-2)=1/4$ trong miền. § Khoảng thuận lợi dài 2. § Tích phân mật độ trên khoảng bằng $2/4$.',r'$1/2$.','Phân bố đều biến xác suất thành tỷ lệ độ dài.'),
E(r'Tìm c để $f(x)=cx$ trên $[0,2]$ là mật độ.',r'Chuẩn hóa: $\int_0^2cx\,dx=2c=1$. § Suy ra c bằng một nửa. § Mật độ không âm trên miền nên điều kiện còn lại cũng thỏa.',r'$c=1/2$.','Không cần mật độ luôn nhỏ hơn 1 tại mọi điểm.'),
E(r'Tuổi thọ $T\sim\operatorname{Exp}(0.1)$, thời gian tính bằng giờ. Tính $P(T>10)$.',r'Hàm sống của phân bố mũ là $e^{-\lambda t}$. § Thay lambda bằng 0.1 và t bằng 10. § Tích lambda t bằng 1 là đại lượng không đơn vị.',r'$P(T>10)=e^{-1}\approx0.3679$.','Đơn vị của lambda là nghịch đảo đơn vị thời gian.'),
E(r'Với tuổi thọ mũ trên, tính $P(T>15\mid T>5)$.',r'Viết xác suất điều kiện bằng $P(T>15)/P(T>5)$. § Tỷ số là $e^{-1.5}/e^{-0.5}=e^{-1}$. § Đây cũng là xác suất sống thêm 10 giờ từ ban đầu.',r'$e^{-1}$.','Tính không nhớ là giả thiết đặc biệt của phân bố mũ, không đúng cho mọi tuổi thọ.'),
E(r'$X\sim N(100,15^2)$. Viết $P(X\le130)$ qua CDF chuẩn.',r'Chuẩn hóa $Z=(X-100)/15$. § Ngưỡng 130 tương ứng z bằng 2. § Do đó xác suất là $\Phi(2)$, xấp xỉ 0.97725.',r'$P(X\le130)=\Phi(2)\approx0.97725$.','Mẫu số là độ lệch chuẩn 15, không phải phương sai 225.')],R))
s.append(S('joint-transform','Phân bố đồng thời, độc lập và biến đổi',r'Phân bố đồng thời mô tả phụ thuộc; mật độ biên được lấy bằng tích phân hoặc tổng theo biến còn lại. Độc lập tương đương phân bố đồng thời phân tích thành tích hai biên. § Với biến đổi một–một khả vi, mật độ mới nhân trị tuyệt đối Jacobian nghịch đảo; với biến đổi nhiều–một cần cộng các nhánh. Không được tự giả sử độc lập chỉ vì chưa biết sự phụ thuộc.',r'Xác định miền hỗ trợ chung. § Lấy biên hoặc mô tả các nhánh nghịch đảo. § Kiểm tra chuẩn hóa của mật độ mới.','Miền tam giác thường tạo phụ thuộc dù công thức mật độ trông đơn giản.',[
E(r'Mật độ chung bằng 2 trên $0<x<y<1$. Tìm mật độ của Y.',r'Với y cố định trong $(0,1)$, x chạy từ 0 đến y. § Tích phân $\int_0^y2dx=2y$. § Chuẩn hóa $\int_0^12ydy=1$.',r'$f_Y(y)=2y$ trên $(0,1)$.','Cận lấy biên phải phản ánh đúng miền tam giác.'),
E(r'X và Y độc lập Bernoulli(1/2). Tìm phân bố S=X+Y.',r'Có bốn cặp đồng xác suất $(0,0),(0,1),(1,0),(1,1)$. § Tổng 0 và 2 có một cặp, tổng 1 có hai cặp. § Gom các xác suất theo tổng.',r'$P(S=0,1,2)=(1/4,1/2,1/4)$.','Tổng hai Bernoulli độc lập cùng tham số là một binomial.'),
E(r'$X\sim U(0,1)$, $Y=2X+1$. Tìm mật độ Y.',r'Nghịch đảo là $x=(y-1)/2$, miền Y là $(1,3)$. § Đạo hàm nghịch đảo bằng $1/2$. § Nhân mật độ X bằng 1 với hệ số Jacobian.',r'$f_Y(y)=1/2$ trên $(1,3)$.','Giãn độ dài gấp đôi làm mật độ giảm một nửa.'),
E(r'$X\sim U(-1,1)$, $Y=X^2$. Tìm CDF và mật độ Y.',r'Với $0\le y\le1$, điều kiện là $-\sqrt y\le X\le\sqrt y$. § Xác suất bằng độ dài $2\sqrt y$ chia 2, nên F(y) bằng $\sqrt y$. § Đạo hàm trong $(0,1)$ cho $1/(2\sqrt y)$.',r'$F_Y(y)=\sqrt y$, $f_Y(y)=1/(2\sqrt y)$ trong miền hỗ trợ.','Hai nhánh cộng lại là yếu tố cần thiết trong biến đổi bình phương.'),
E(r'Nếu $X,Y$ độc lập mũ tốc độ lambda, tìm $P(\min(X,Y)>t)$.',r'Min lớn hơn t khi cả X và Y đều lớn hơn t. § Độc lập cho tích hai hàm sống $e^{-\lambda t}e^{-\lambda t}$. § Gộp số mũ được $e^{-2\lambda t}$.',r'Giá trị nhỏ nhất có phân bố mũ tốc độ $2\lambda$.','Mô hình này cũng diễn tả thời gian hỏng của hai phần tử mắc nối tiếp độc lập.')],R))
s.append(S('moments','Kỳ vọng, phương sai, hiệp phương sai và hàm sinh moment',r'Kỳ vọng tuyến tính không cần độc lập. Phương sai $\operatorname{Var}X=E[X^2]-(EX)^2$ đo bình phương độ phân tán. Với tổng, cần cộng các phương sai và hai lần các hiệp phương sai. § Hàm sinh moment $M_X(t)=E[e^{tX}]$ nếu hữu hạn quanh 0 có đạo hàm cho các moment. Độc lập làm hàm sinh của tổng thành tích; không phải mọi phân bố đều có MGF hữu hạn ngoài 0.',r'Tính kỳ vọng và moment bậc hai. § Giữ các hiệp phương sai nếu chưa có độc lập. § Kiểm tra phương sai không âm.','Không tương quan không đồng nghĩa độc lập trong phân bố tổng quát.',[
E(r'Xúc xắc công bằng: tìm EX và Var X.',r'$EX=(1+\cdots+6)/6=7/2$. § $E[X^2]=91/6$. § Lấy $91/6-49/4=35/12$.',r'$EX=3.5$, $\operatorname{Var}X=35/12$.','Phương sai sử dụng moment bậc hai, không phải trung bình trị tuyệt đối độ lệch.'),
E(r'X là số sản phẩm lỗi trong 100 sản phẩm độc lập, mỗi sản phẩm lỗi với xác suất 0.02.',r'Viết X là tổng 100 chỉ báo lỗi. § Mỗi chỉ báo có kỳ vọng 0.02 và phương sai $0.02\cdot0.98$. § Cộng kỳ vọng và phương sai nhờ độc lập.',r'$EX=2$, $\operatorname{Var}X=1.96$.','Biểu diễn bằng chỉ báo giúp suy ra công thức binomial.'),
E(r'Nếu EX=2, Var X=3, tìm E(4X-1) và Var(4X-1).',r'Tuyến tính cho kỳ vọng $4\cdot2-1=7$. § Cộng hằng số không đổi phương sai. § Nhân 4 làm phương sai nhân $4^2$.',r'Kỳ vọng 7, phương sai 48.','Đơn vị bình phương giải thích vì sao hệ số bị bình phương.'),
E(r'Cho Var X=Var Y=1 và Cov(X,Y)=0.3. Tính Var(X+Y).',r'Công thức tổng cho $\operatorname{Var}(X+Y)=\operatorname{Var}X+\operatorname{Var}Y+2\operatorname{Cov}(X,Y)$. § Thay số được $1+1+0.6$. § Hiệp phương sai dương làm tổng phân tán hơn trường hợp không tương quan.',r'Phương sai bằng 2.6.','Bỏ hiệp phương sai khi các biến phụ thuộc có thể làm sai kết quả.'),
E(r'Tìm MGF của Bernoulli(p) và suy ra kỳ vọng.',r'X nhận 0 và 1, nên $M(t)=(1-p)+pe^t$. § Đạo hàm $M\prime(t)=pe^t$. § Tại 0 cho $M\prime(0)=p$.',r'$M(t)=1-p+pe^t$, $EX=p$.','MGF gói các moment vào các đạo hàm tại gốc.')],R))
s.append(S('limits','Luật số lớn, CLT và xấp xỉ',r'Với các biến độc lập cùng phân bố có kỳ vọng hữu hạn, trung bình mẫu hội tụ về kỳ vọng theo luật số lớn. Khi phương sai hữu hạn dương, CLT cho trung bình chuẩn hóa hội tụ theo phân phối đến chuẩn. § Đây là các kết quả tiệm cận, không bảo đảm xấp xỉ chính xác cho mọi n. Bất đẳng thức Chebyshev cho chặn hữu hạn mẫu; hiệu chỉnh liên tục cải thiện một số xấp xỉ chuẩn cho số đếm.',r'Kiểm tra độc lập, cùng phân bố và moment. § Chuẩn hóa bằng sai số chuẩn sigma trên căn n. § Nêu xấp xỉ và kiểm tra điều kiện phù hợp.','Tăng số mẫu không tự loại được thiên lệch lấy mẫu.',[
E(r'Xi độc lập có trung bình 10, phương sai 4. Tìm phương sai trung bình của 100 biến.',r'Tổng có phương sai $100\cdot4=400$. § Chia tổng cho 100 làm phương sai chia $100^2$. § Kết quả bằng 0.04, sai số chuẩn bằng 0.2.',r'$\operatorname{Var}\bar X=0.04$.','Trung bình giảm độ lệch chuẩn theo căn số mẫu.'),
E(r'Dùng Chebyshev chặn $P(|\bar X-10|\ge1)$ trong ví dụ trên.',r'Phương sai trung bình là 0.04. § Chebyshev cho xác suất không vượt phương sai chia bình phương ngưỡng. § Với ngưỡng 1, chặn bằng 0.04.',r'Xác suất không vượt 4%.','Chặn này không đòi giả thiết chuẩn nhưng có thể khá lỏng.'),
E(r'$X\sim\operatorname{Bin}(100,0.5)$. Xấp xỉ $P(45\le X\le55)$.',r'Trung bình 50, độ lệch chuẩn 5. § Hiệu chỉnh liên tục dùng khoảng $[44.5,55.5]$. § Chuẩn hóa thành $[-1.1,1.1]$, xác suất xấp xỉ $2\Phi(1.1)-1$.',r'Xấp xỉ 0.7287.','Hai đầu khoảng nửa nguyên cải thiện việc nối số đếm rời rạc với chuẩn liên tục.'),
E(r'Nếu muốn sai số chuẩn giảm một nửa, cần tăng số mẫu bao nhiêu lần?',r'Sai số chuẩn tỷ lệ với $1/\sqrt n$. § Muốn $1/\sqrt{n_{\rm new}}=(1/2)/\sqrt n$. § Bình phương hai vế cho số mẫu mới gấp 4.',r'Tăng số mẫu 4 lần.','Muốn tăng độ chính xác không thể chỉ tăng mẫu theo tỷ lệ tuyến tính.'),
E(r'Quan sát tần suất mặt ngửa 0.52 sau 1000 lần tung. Luật số lớn có chứng minh đồng xu công bằng không?',r'Luật số lớn nói tần suất tiến về xác suất thật khi các phép thử phù hợp. § Một quan sát hữu hạn 0.52 có thể xuất hiện với nhiều giá trị p. § Cần bài toán ước lượng hoặc kiểm định, không được đảo chiều định lý.',r'Không đủ để chứng minh p bằng 0.5.','Định lý hội tụ và suy luận thống kê là hai loại phát biểu khác nhau.')],R))
s.append(S('processes','Quá trình Poisson, Markov và độ tin cậy',r'Quá trình Poisson thuần nhất tốc độ lambda có gia số độc lập, dừng và số sự kiện trong khoảng t có phân bố Poisson(lambda t). Thời gian giữa các sự kiện độc lập có phân bố mũ. § Chuỗi Markov mô hình hóa bước kế tiếp phụ thuộc trạng thái hiện tại qua ma trận chuyển P; phân bố sau n bước là $\pi_0P^n$. Mô hình độ tin cậy nối tiếp/song song cần nêu rõ độc lập và cách định nghĩa hệ còn hoạt động.',r'Xác định thời gian rời rạc hay liên tục. § Viết tốc độ hoặc ma trận chuyển đúng đơn vị. § Tính bằng mô hình và kiểm tra tổng xác suất.','Trạng thái dừng không tự đảm bảo phân bố hội tụ nếu chuỗi tuần hoàn hoặc không có điều kiện phù hợp.',[
E(r'Cuộc gọi đến theo Poisson tốc độ 3 mỗi giờ. Xác suất không có cuộc gọi trong 20 phút?',r'Đổi 20 phút thành $1/3$ giờ. § Số cuộc gọi có tham số $3\cdot1/3=1$. § Xác suất số đếm bằng 0 là $e^{-1}$.',r'Khoảng 0.3679.','Không dùng t bằng 20 khi tốc độ đang tính theo giờ.'),
E(r'Với tốc độ 3 mỗi giờ, thời gian chờ trung bình đến cuộc gọi kế tiếp?',r'Thời gian chờ là mũ với tốc độ 3. § Kỳ vọng bằng nghịch đảo tốc độ, $1/3$ giờ. § Đổi sang phút được 20 phút.',r'20 phút.','Tham số tốc độ và kỳ vọng có quan hệ nghịch đảo.'),
E(r'Chuỗi hai trạng thái có $P=\begin{pmatrix}0.8&0.2\\0.3&0.7\end{pmatrix}$, ban đầu ở trạng thái 1. Phân bố sau hai bước?',r'Sau một bước là $(0.8,0.2)$. § Nhân thêm P: xác suất trạng thái 1 là $0.8^2+0.2\cdot0.3=0.7$. § Xác suất còn lại bằng 0.3.',r'$\pi_2=(0.7,0.3)$.','Các hàng P cộng bằng 1, nên nhân phân bố hàng ở bên trái.'),
E(r'Tìm phân bố dừng cho ma trận trên.',r'Đặt $\pi=(a,1-a)$ và giải $a=0.8a+0.3(1-a)$. § Suy ra $0.5a=0.3$, tức a=0.6. § Nhân lại $(0.6,0.4)P$ xác nhận không đổi.',r'$\pi=(0.6,0.4)$.','Cần cả phương trình dừng và chuẩn hóa tổng bằng 1.'),
E(r'Hai phần tử độc lập có độ tin cậy 0.9 và 0.8. So sánh mắc nối tiếp và song song.',r'Nối tiếp hoạt động khi cả hai hoạt động, nên xác suất $0.9\cdot0.8$. § Song song chỉ hỏng khi cả hai hỏng, xác suất $0.1\cdot0.2$. § Lấy phần bù cho độ tin cậy song song.',r'Nối tiếp 0.72; song song 0.98.','Độc lập là giả thiết quan trọng; hỏng chung có thể làm lợi ích dự phòng giảm mạnh.')],R))
save('eas-305',['Đếm cơ bản, tích phân một biến'],['Chọn mô hình xác suất cho bài toán kỹ thuật','Tính phân bố và đặc trưng biến ngẫu nhiên','Đánh giá xấp xỉ, độ tin cậy và quá trình đếm'],s)
